// Some portions generated by Claude Code

const test = require('node:test');
const assert = require('node:assert/strict');

const { createListBrowserHarness } = require('./list-browser-harness.js');

// Review finding B1: a kept-alive (suspended) Query page still reports isMounted() and its paging methods are
// stubs returning false, so Explore's Previous/Next must never be handed to it.
test('Explore Previous/Next navigate while a kept-alive Query page is parked', () => {
    const navigations = [];
    const handedToQueryPage = [];
    const harness = createListBrowserHarness({
        href: 'http://localhost:8080/rdf4j-workbench/repositories/test/explore?resource=%3Chttp%3A%2F%2Fex%2Fa%3E',
        workbench: {
            router: { isRunning: () => true, navigate: (url) => navigations.push(url) },
            queryPage: {
                isMounted: () => true,
                nextPage() { handedToQueryPage.push('next'); return false; },
                previousPage() { handedToQueryPage.push('previous'); return false; },
                changePageParameter(name) { handedToQueryPage.push(name); return false; }
            }
        }
    });
    harness.document.cookie = 'total_result_count=100';
    const limit = harness.registerElement('select', { id: 'limit_explore', value: '10' });
    harness.document.body.appendChild(limit);
    harness.loadPagingScripts([]);
    const paging = harness.context.workbench.paging;

    paging.nextOffset('explore');
    assert.deepEqual(handedToQueryPage, [], 'Explore paging is not handed to the parked Query page');
    assert.equal(navigations.length, 1, 'Next navigates the Explore page');
    assert.match(navigations[0], /offset=10/);

    harness.document.location.href = navigations[0];
    paging.previousOffset('explore');
    assert.equal(navigations.length, 2, 'Previous navigates the Explore page');
    assert.match(navigations[1], /offset=0/);

    paging.addPagingParam('offset', 20);
    paging.addGraphParam('limit_explore');
    assert.deepEqual(handedToQueryPage, []);
    assert.equal(navigations.length, 4);
});

function explorePagingHarness(href, selectValue) {
    const navigations = [];
    const harness = createListBrowserHarness({
        href,
        workbench: { router: { isRunning: () => true, navigate: (url) => navigations.push(url) } }
    });
    harness.document.cookie = 'total_result_count=1000';
    const select = harness.registerElement('select', { id: 'limit_explore', value: selectValue });
    // The view renders the page's limit as the selected option; changing the select applies nothing by itself.
    select.options = ['0', '10', '50', '100', '200'].map((value) => harness.registerElement('option',
        { value, attributes: { value } }));
    select.options.forEach((option) => { option.defaultSelected = option.value === '100'; });
    harness.document.body.appendChild(select);
    harness.loadPagingScripts([]);
    return { harness, navigations, paging: harness.context.workbench.paging };
}

// Review finding B3: Explore's 'Show datatypes' must not hide datatype tags on the pages shown after it.
test('Explore Show datatypes marks only its own page, both ways on every mount', () => {
    const harness = createListBrowserHarness({
        href: 'http://localhost:8080/rdf4j-workbench/repositories/test/explore?resource=x'
    });
    harness.document.cookie = 'show-datatypes=false';
    harness.loadPagingScripts([]);
    const outlet = harness.registerElement('div', { id: 'outlet' });
    const checkbox = harness.registerElement('input', { type: 'checkbox', name: 'show-datatypes', checked: true });
    outlet.appendChild(checkbox);
    harness.document.body.appendChild(outlet);
    const paging = harness.context.workbench.paging;

    paging.setShowDataTypesCheckboxAndSetChangeEvent(outlet);
    assert.equal(checkbox.checked, false);
    assert.equal(outlet.classList.contains('workbench-hide-datatypes'), true, 'the Explore page hides its tags');
    assert.equal(harness.document.body.classList.contains('workbench-hide-datatypes'), false,
        'the body (and so every later page) is left alone');

    checkbox.checked = true;
    checkbox.trigger('change');
    assert.equal(outlet.classList.contains('workbench-hide-datatypes'), false);
    assert.match(harness.document.cookie, /show-datatypes=true/);

    // The next Explore page may be rendered into the same outlet: its mount sets the class from the cookie.
    outlet.classList.add('workbench-hide-datatypes');
    const next = harness.registerElement('input', { type: 'checkbox', name: 'show-datatypes', checked: true });
    outlet.appendChild(next);
    paging.setShowDataTypesCheckboxAndSetChangeEvent(outlet);
    assert.equal(outlet.classList.contains('workbench-hide-datatypes'), false);
});

test('the hide-datatypes style only applies to Explore results', () => {
    const fs = require('node:fs');
    const path = require('node:path');
    const css = fs.readFileSync(path.resolve(__dirname,
        '../../tools/workbench/src/main/webapp/styles/workbench-refresh.css'), 'utf8').replace(/\/\*[\s\S]*?\*\//g, '');
    const rules = css.split('}').filter((rule) => rule.includes('workbench-hide-datatypes'));
    assert.ok(rules.length > 0);
    for (const rule of rules) {
        const selectors = rule.substring(0, rule.indexOf('{')).split(',').map((selector) => selector.trim());
        for (const selector of selectors.filter(Boolean)) {
            assert.match(selector, /#explore-results \.rdf-datatype$/, selector + ' must be scoped to Explore results');
        }
    }
});

test('paging keeps its page-request paths: matrix URLs, embedded query text and pages without the router', () => {
    const navigations = [];
    const harness = createListBrowserHarness({
        href: 'http://localhost:8080/rdf4j-workbench/repositories/test/explore',
        workbench: { router: { isRunning: () => true, navigate: (url) => navigations.push(url) } }
    });
    const limit = harness.registerElement('select', { id: 'limit_explore', value: '50' });
    harness.document.body.appendChild(limit);
    harness.loadPagingScripts([]);
    const paging = harness.context.workbench.paging;
    paging.addGraphParam('limit_explore');
    assert.equal(navigations[0], 'http://localhost:8080/rdf4j-workbench/repositories/test/explore;limit_explore=50');

    harness.document.location.href = 'http://localhost:8080/rdf4j-workbench/repositories/test/query';
    harness.document.cookie = 'query=SELECT%20*; ref=text';
    paging.addPagingParam('offset', 3);
    const fromCookies = harness.document.lastSubmittedForm.serializeArray();
    assert.equal(fromCookies.find((entry) => entry.name === 'query').value, 'SELECT *', 'the query cookie is posted');

    const text = harness.registerElement('textarea', { id: 'wb-query-text', value: 'ASK {}' });
    harness.document.body.appendChild(text);
    paging.addPagingParam('offset', 5);
    const posted = harness.document.lastSubmittedForm.serializeArray();
    assert.equal(posted.find((entry) => entry.name === 'query').value, 'ASK {}');
    assert.equal(posted.find((entry) => entry.name === 'ref').value, 'text');

    harness.context.workbench.router = null;
    harness.document.location.href = 'http://localhost:8080/rdf4j-workbench/repositories/test/explore?resource=x';
    paging.addPagingParam('offset', 10);
    assert.match(harness.document.location.href, /offset=10/, 'without the router the page loads');
});

test('the applied limit falls back to the select when the URL limit is not a number or no option is the default', () => {
    const { paging } = explorePagingHarness(
        'http://localhost:8080/rdf4j-workbench/repositories/test/explore?resource=x&limit_explore=many', '200');
    assert.equal(paging.getLimit('explore'), 100, 'the rendered default');
    const plain = createListBrowserHarness({
        href: 'http://localhost:8080/rdf4j-workbench/repositories/test/explore?resource=x'
    });
    const select = plain.registerElement('select', { id: 'limit_explore', value: '10' });
    select.options = [plain.registerElement('option', { value: '10' })];
    select.options[0].defaultSelected = false;
    plain.document.body.appendChild(select);
    plain.loadPagingScripts([]);
    assert.equal(plain.context.workbench.paging.getLimit('explore'), 10);
});

// Review finding B28: Next/Previous step by the limit applied to the shown page, not the unapplied select value.
test('Explore Next steps by the applied URL limit, not a changed Result limit select', () => {
    const { navigations, paging } = explorePagingHarness(
        'http://localhost:8080/rdf4j-workbench/repositories/test/explore?resource=x&limit_explore=100&offset=0', '200');
    paging.nextOffset('explore');
    assert.match(navigations[0], /offset=100(&|$)/);
    assert.match(navigations[0], /limit_explore=100/);
});

test('Explore Previous steps by the applied URL limit', () => {
    const { navigations, paging } = explorePagingHarness(
        'http://localhost:8080/rdf4j-workbench/repositories/test/explore?resource=x&limit_explore=100&offset=200', '50');
    paging.previousOffset('explore');
    assert.match(navigations[0], /offset=100(&|$)/);
});

test('Explore Next without a URL limit steps by the limit the page was rendered with, even after choosing All', () => {
    const { navigations, paging } = explorePagingHarness(
        'http://localhost:8080/rdf4j-workbench/repositories/test/explore?resource=x', '0');
    assert.equal(paging.getLimit('explore'), 100);
    paging.nextOffset('explore');
    assert.match(navigations[0], /offset=100(&|$)/, 'All in the select does not make Next reload the same page');
});
